public static int[] calculateFinishTimes(int N, int A, int[] T) {
    int currentTime = 0;
    int[] finishTimes = new int[N];

    for (int i = 0; i < N; i++) {
        if (T[i] > currentTime) {
            currentTime = T[i];
        }
        finishTimes[i] = currentTime + A;
        currentTime += A;
    }

    return finishTimes;
}
